SELECT jsonb_build_object('database',current_database(),'migration_count',(SELECT count(*) FROM drizzle.__drizzle_migrations),'journal',(SELECT jsonb_agg(to_jsonb(m) ORDER BY created_at,id) FROM drizzle.__drizzle_migrations m),'backup_tables',(SELECT count(*) FROM qa_recovery_20261012.table_manifest),'backup_rows',(SELECT sum(row_count) FROM qa_recovery_20261012.table_manifest),'typing_texts',(SELECT count(*) FROM typing_texts),'assignment_targets',(SELECT count(*) FROM assignment_targets),'private_schema_anon_usage',has_schema_privilege('anon','qa_recovery_20261012','USAGE'),'private_schema_authenticated_usage',has_schema_privilege('authenticated','qa_recovery_20261012','USAGE')) AS qa_repair_evidence;
SELECT table_name,row_count,rows_md5,original_columns FROM qa_recovery_20261012.table_manifest ORDER BY table_name;
